package org.genhttp.api.protocol

/**
 * Allows the response generated by a builder or handler to be adjusted.
 *
 * This can be useful if you would like to add behavior that the original handler (such as a page renderer)
 * does not provide. For example, as the page handlers implement this interface, you can add a header to
 * the response being generated for a page.
 *
 * @param TBuilder The type of builder used as a return value
 */
public interface ResponseModification<out TBuilder> {

    /**
     * Specifies the HTTP status code of the response.
     *
     * @param status The HTTP status code of the response
     */
    public fun status(status: ResponseStatus): TBuilder

    /**
     * Specifies how the server should treat the connection after this response has been sent.
     *
     * @param handling The mode to be applied
     */
    public fun connection(handling: Connection): TBuilder

    /**
     * Sets the given header field on the response. Changing HTTP protocol headers may cause incorrect behavior.
     *
     * @param key The name of the header to be set
     * @param value The value of the header field
     */
    public fun header(key: String, value: String): TBuilder

    /**
     * Adds a cookie with the given name, value and attributes to the response.
     *
     * @param name The name of the cookie
     * @param value The value of the cookie
     * @param options The attributes to be set on the cookie
     */
    public fun cookie(name: String, value: String, options: CookieOptions = CookieOptions()): TBuilder

}
